INSERT INTO public.document_chunks VALUES ('b8b7af3a-96f4-4d37-982c-f014b620e343', '0571cbfe-2a12-4c4b-a971-06b338bb8260', 19, 'máy tính điện tửngày một “nhanh” hơn
• Nguy cơ tấn công vét cạn khóa ngày càng rõ
• Năm 1981, công nghệmáy tính lượng tửđược đềxuất bởi  
Richard Feynman kéo theo nhu cầu vềmột hệmật mã an 
toàn có thểsửdụng trong tương lai xa hơn
• Chính phủHoa Kỳgiao cho NIST khởi động dựán thiết kế
hệmật mã tiên tiến từnăm 1997
• Hệmật mã Rijmen được lựa chọn từ15 thiết kế
• Thiết kếvà ciới thiệu bởi V. Rijmen và cộng sựvào năm 1998
• Chuẩn hóa thành AES (Advanced Encryption Standard) vào năm 
2002', '[-0.08382583,0.083757184,-0.021901898,-0.08625281,-0.037983824,0.0076711755,0.037828635,0.013844873,0.04194196,0.008090798,0.10664307,-0.014474505,-0.017076615,-0.022122452,0.02848677,-0.023717746,-0.062778406,-0.019591413,-0.06551912,-0.06182671,-0.007784799,-0.02766048,-0.012447418,-0.0369234,0.009322645,0.031633463,0.0063594454,0.046699874,-0.014175679,-0.019069362,-0.050333396,0.14665276,0.016774876,0.024036443,-0.012068899,-0.033117365,0.0014976438,-0.011522224,0.013909945,0.020226195,-0.07612223,-0.12808974,0.0052933274,-0.06569713,0.013831004,0.010802729,-0.009141195,0.019170418,-0.025426736,-0.0045867446,-0.0638465,0.12423006,-0.022475285,0.057728503,-0.10392591,-0.08171047,-0.04408724,0.08669364,-0.007452253,-0.1033483,-0.04053799,0.06806439,-0.093819566,-0.0077258195,0.024488198,0.055777796,0.037233472,-0.034818146,-0.013168369,0.05704065,-0.022901885,-0.020156577,-0.08875658,0.076490864,-0.12004483,0.012378633,0.016992634,0.026163774,0.042694625,-0.057472836,-0.0026184546,-0.0076123197,0.07938009,-0.055338025,-0.055981647,0.046667445,-0.07746511,-0.011430553,-0.034557372,-0.048397392,0.060099225,0.0133729335,0.0364411,0.03385736,-0.0130427,-0.03070529,-0.01258047,0.03530051,-0.02601462,0.05549465,0.054441094,0.034749154,-0.047582615,-0.03961033,-0.06638531,0.014390956,0.06039986,-0.027073966,0.040995568,-0.020058464,-0.0689414,-0.043036226,0.031696025,-0.124050215,0.011374474,-0.022631036,-0.07199374,0.0461094,-0.008234865,0.08425689,0.006901595,-0.015217037,-0.03824505,0.032171108,-0.062257506,-0.03302913,0.057356767,2.6165855e-32,0.011691379,0.02995718,-0.00019988972,-0.028221602,-0.02574665,0.03664435,-0.01961849,-0.037963804,-0.108171165,-0.016559266,-0.03844644,-0.046576966,-0.04293535,-0.15168215,0.051124536,0.00535819,0.026526779,-0.060459953,0.0025940782,-0.013950071,0.022185877,-0.019213047,0.09259793,-0.013820232,0.017402962,-0.0026026862,0.008365133,-0.046014305,0.0074629555,0.07442624,0.03189092,0.0027318262,-0.015852984,-0.07923502,-0