INSERT INTO public.document_chunks VALUES ('1eac36e6-a693-4d4b-b4fc-71a5f0ae99da', '0571cbfe-2a12-4c4b-a971-06b338bb8260', 39, 'cần an toàn ngay cảđối phương biết mọi thông tin 
vềhệ, trừkhóa bí mật”
• Kẻthám mã đã biết giải thuật sinh khóa, mã hóa, giải 
mã nhưng không biết khóa bí mật
• Tấn công chỉbiết bản mật:
• Kẻthám mã có các bản mật (COA: ciphertext-only 
attack)
• Phương pháp phá mã: thửtất cảcác tổhợp khóa có
thểđểtìm ra tổhợp khóa thích hợp. Trong trường
hợp không gian khóa lớn thì phương pháp này không
thực hiện được.
• Đối phương cần phải phân tích văn bản mật, thực hiện', '[-0.062376034,0.07988936,-0.049372166,-0.09003949,-0.08652627,0.01099663,0.08209583,-0.034663994,0.05669069,0.07821153,0.13855176,-0.062177394,0.0042959573,0.028124996,0.054640885,-0.045024984,-0.040125486,0.079626404,-0.07006702,-0.02811636,0.006652985,-0.014644519,-0.011534428,-0.012501001,-0.052885547,0.051173963,-1.3966657e-05,0.082377926,0.026680514,-0.066121265,-0.00509011,0.13256052,0.03972145,-0.0233565,-0.014225442,0.050454635,-0.059848085,-0.031489085,0.058862597,0.04202394,-0.014092795,-0.017058186,0.013977009,-0.13563159,0.032734156,-0.022322439,-0.057889264,-0.010472752,-0.032774646,-0.039993677,-0.043166462,0.065427475,-0.0012018137,0.067136,-0.121614195,-0.06457383,-0.03969018,0.1166841,0.035457674,-0.022841087,-0.04191754,0.010102903,-0.051772892,-0.0074658846,0.031399533,-0.074946344,-0.09755502,-0.042331025,0.00065910723,0.09116403,-0.0402845,-0.034681555,-0.022263829,0.10704307,0.011653886,0.055011448,0.0149348,-0.012753681,-0.020699644,-0.064832784,0.017644355,0.011195335,0.03931122,-0.045942936,-0.04239091,0.052417602,-0.03033971,0.04030654,0.04111439,-0.07138948,0.09007284,0.107261315,0.0071508307,0.010151735,-0.055861965,-0.065108106,-0.025192041,0.03285733,-0.051759228,0.015271126,0.039870773,-0.0115426425,0.00087460486,-0.057420935,-0.07458713,0.0028511928,0.05321616,-0.06601426,0.025688509,0.010949313,-0.0631504,-0.03668655,0.07482326,-0.1500731,-0.02814928,0.041624926,-0.029189633,-0.028807605,-0.015172489,0.041972805,-0.0092546595,-0.096750975,0.027146786,0.019954305,-0.02052513,-0.044880316,0.008058328,2.0244096e-32,0.039466165,0.07164699,-0.01034146,-0.042080514,0.023649419,-0.028486315,-0.03344908,-0.087119415,-0.015160094,-0.07465736,0.023005629,-0.0052467445,-0.055053547,-0.045127522,0.016389964,0.02558571,0.111113444,-0.06951089,0.007815709,-0.014001476,0.026356366,-0.031932894,0.02013064,0.020541163,0.046670444,-0.019717166,0.008405901,-0.057952806,-0.026862094,0.04023312,0.