INSERT INTO public.document_chunks VALUES ('c9d10c5f-10d3-41f2-be46-db41aa3ffdfd', '0571cbfe-2a12-4c4b-a971-06b338bb8260', 80, 'tường bóng đèn đối lưu
Bộsinh sốgiảngẫu nhiên
• PRNG: Pseudo Random Number Generator
• Thuật toán biến đổi 1 chuỗi bit thực sựngẫu nhiên 
seed (sốhạt mầm) có kích thước ngắn thành 1 
chuỗi bit dài hơn và “trông giống như” ngẫu nhiên
• Hàm PNRG có tính xác định: chuỗi bit đầu ra được 
sinh theo thuật toán
• Nhưng đối với kẻtấn công, nếu không biết được seed thì 
không thểphân biệt sựkhác nhau giữa đầu ra của hàm 
PRNG với chuỗi bit ngẫu nhiên thực sự', '[-0.07394606,0.028206196,-0.029736595,-0.08501622,-0.06355712,-0.009559904,0.08485368,-0.013665279,0.05742531,0.036056925,0.106302224,-0.068672776,-0.0015027261,-0.09933135,0.013253379,-0.050317913,-0.0510524,0.010874769,-0.045209743,-0.093828596,-0.024466503,0.030749034,0.020180816,0.006342701,0.058887616,-0.010287632,-0.00039977062,0.09945282,0.12722301,-0.08287855,0.033215486,0.1800728,0.052954797,-0.049832266,0.046119977,0.062100198,-0.041777384,-0.0027520172,0.015257462,0.05866812,-0.0039860737,-0.05007098,0.008224756,-0.06648129,0.021464806,0.019255713,-0.09425122,0.034874864,-0.011167949,0.0035628234,-0.0360913,0.042759974,-0.019305471,0.090500616,-0.11196085,-0.07030884,-0.010144756,0.08034443,0.0017870859,-0.054325286,-0.04073653,0.027335387,-0.07664858,-0.0661971,-0.004641486,-0.03383047,-0.0047202073,0.009562004,0.00036616507,0.022562165,0.01955734,0.0200693,-0.063258246,0.11149331,-0.059204195,0.063213214,-0.060460467,-0.039337512,-0.011618064,-0.088958204,-0.001960206,0.009301152,0.17411914,-0.096433386,-0.04470367,0.046832494,-0.0012677829,0.0659537,-0.027535291,-0.049087312,-0.025662147,0.05836101,0.020015962,0.051703732,-0.022570314,0.063333,0.00077130744,-0.008472276,-0.015720466,0.03423419,0.05129255,0.057847977,0.013355427,-0.05354663,-0.039874904,0.0053853737,0.0045425165,-0.02050818,0.109616324,-0.005991153,-0.01154055,-0.013862335,0.0027782833,-0.10291504,-0.054289054,-0.024123058,-0.097806305,-0.0062273494,-0.06533391,-0.03462314,-0.019194711,-0.008229136,-0.08747146,0.036000703,-0.06332606,-0.03380466,0.08223937,2.0826452e-32,0.047780868,-0.0013424217,0.013224608,-0.054515854,0.043487545,-0.035379816,-0.0061712814,-0.043503802,-0.041557852,-0.012529721,-0.05338273,-0.018665398,-0.081907995,-0.02420434,0.046020385,-0.06923412,0.012748682,-0.053495258,0.021768842,-0.012984472,-0.011911393,0.03367992,-0.015645403,-0.0155331,0.10775158,0.0064266087,-0.018318424,-0.046030022,-0.030040214,0.05296283,0.051772