INSERT INTO public.document_chunks VALUES ('e4fb66c4-004a-402c-b083-35f1df793128', '0571cbfe-2a12-4c4b-a971-06b338bb8260', 82, 'ngẫu nhiên và một chuỗi bit là đầu ra của PRNG
• PRNG là an toàn nếu xác suất phân biệt đúng không 
lớn hơn ½ + ε
• Định nghĩa tương đương: kẻtấn công không thể
đoán được chuỗi bit đầu ra của PRNG
105
PRNG: Chống hồi phục (rollback resistant)
• Dù kẻtấn công biết được kết quảcủa một bước 
trung gian, hắn cũng không học được gì vềkết của 
bước tính toán trước đó hoặc giá trịđầu ra.
• Thửthách: kẻtấn công biết được kết quảtính toán 
trung gian và cần phân biệt một chuỗi bit ngẫu', '[-0.0772316,0.05221485,-0.05129035,-0.11689375,-0.09783567,0.0060964962,0.08214704,0.05252378,0.05233431,0.027123943,0.1295255,-0.049863912,0.009503231,-0.03022692,0.00995901,-0.054803457,-0.06488776,0.05606851,-0.07455948,-0.058680017,-0.08872084,0.018962476,0.0127649,0.0131925475,-0.007189143,0.03139774,0.013084707,0.030480057,0.062484346,-0.120818384,0.018495303,0.15371089,0.0032749176,-0.007609402,0.02297077,0.044973977,-0.065870695,-0.023567138,0.07136469,0.024306264,-0.0065142093,-0.04224176,-0.03415843,-0.10799985,0.08913996,-0.0075502815,-0.07300969,0.029721543,-0.04500534,-0.005427345,0.015837863,0.048582103,-0.011383633,0.07969444,-0.080208674,-0.108553834,-0.03831865,0.09866425,0.050435573,-0.0030322808,-0.023706935,0.032004416,-0.061107334,-0.048003215,-0.010369221,-0.013835131,-0.030281018,-0.049363174,-0.03960585,0.049251165,0.02713992,-0.012573329,-0.1163042,0.036220945,-0.027609058,0.045391012,0.0060849623,0.008804063,-0.047675196,-0.08269801,0.03512608,0.043165367,0.07956393,-0.05186272,-0.033287667,0.017740762,-0.006729798,0.05368014,0.005926229,-0.059832316,0.0008941898,0.13135232,0.07346214,-0.0049898187,0.025432682,0.004467248,-0.042445835,0.02582906,-0.03991166,0.027958263,0.056882463,0.025932603,-0.027136711,-0.03619063,-0.07799682,-0.0007688198,0.07123037,-0.07032135,0.050605524,0.04090831,-0.05867009,-0.0014275593,0.026466686,-0.16563223,-0.051003285,-0.025867062,-0.08796452,0.0046492773,-0.02077222,-0.016931556,0.006036216,0.016763495,-0.061406244,-0.009322409,-0.011877281,-0.038549542,0.075956255,2.2656004e-32,-0.006630855,-0.0043147397,0.014024306,-0.043325786,-0.0021588188,-0.029631637,-0.03642276,-0.10479898,-0.023398137,-0.07730995,-0.016240802,0.01268971,-0.11336382,-0.038533267,0.042551186,0.0058857324,0.053529605,-0.09147583,0.01080743,0.010498788,-0.0036645376,-0.052776944,-0.028204938,0.060971886,0.08041285,-0.03679166,-0.0057174675,-0.030425716,-0.06604153,0.031888835,0.04014586,0