INSERT INTO public.document_chunks VALUES ('73d9783e-97eb-49c4-8cc7-21745dacd32c', 'bf350733-46ca-4024-a499-59ce712b5e83', 6, '• Tính đúng đắn: V(k, m, S(k,m)) = True
• Tính hiệu quả: tính toán được với mọi m trong thời 
gian chấp nhận được
• Tính an toàn: nếu đối phương không biết k
• Không thểtính được t = S(k, m)
• Với t cho trước, không thểtìm được m sao cho S(k, m) = t
• Không thểtìm được m và m* sao cho S(k, m) = S(k, m*)
13
An toàn của MAC
• MAC là an toàn nếu với mọi thuật toán tấn công hiệu quảthì xác 
suất P(b = true) ≤ ε
kẻtấn công không thểtạo giá trịt hợp lệnếu không có khóa k
14
Thử thách
1. Sinh khóa k', '[-0.09341659,0.028143391,-0.009166008,-0.040155783,-0.07691269,0.05388702,0.0970579,-0.006234743,0.09590343,0.036080677,0.19467963,-0.13467887,-0.011405728,-0.014534884,-0.0005383672,-0.003956544,-0.035573598,0.030875158,-0.050523918,-0.005406073,-0.02867161,-0.043569148,-0.048722688,0.058759656,-0.011256943,0.059044126,0.025184039,0.08791581,-0.028957212,-0.017485268,-0.07325985,0.17129385,0.0088583995,-0.05266902,0.077052034,-0.012390701,-0.040704876,-0.05509735,0.004063465,0.0077816932,-0.0604427,-0.043025475,0.034430116,-0.083417766,0.07166056,0.03589444,-0.0023457874,0.025866766,-0.02009687,-0.016124414,-0.016694527,0.11791309,-0.06895823,0.08864915,-0.042376515,0.011693735,-0.041937094,0.0018253054,-0.0024871589,-0.069783345,-0.008259869,0.03603494,-0.07941165,0.010182015,0.033499766,0.015895294,0.0061014188,-0.10226379,-0.048786797,0.0791436,0.026701253,-0.041289534,-0.08906082,0.06958113,-0.068384126,0.014314769,0.007317077,-0.024070336,-0.06569882,-0.08699127,-0.04386746,0.055176638,0.06530673,-0.07785467,0.011331692,0.03313831,-0.049442567,0.019273464,0.007947341,-0.02709934,0.030879533,0.048279885,-0.032322012,-0.04130822,0.009873902,-0.08484649,-0.035561513,0.07084786,0.028134841,0.029912306,0.050234817,-0.024017325,-0.02105669,-0.062300067,-0.081907675,0.043088887,0.05551797,-0.02543662,0.054290462,0.070881695,-0.038377162,-0.068876155,0.04676409,-0.057042476,-0.005917637,0.03301802,-0.0061030854,-0.028583653,0.026127398,0.058067918,0.018172499,-0.021474661,-0.035573978,0.05515058,-0.06184018,-0.051272184,0.06942851,1.715369e-32,0.034596104,0.04631814,0.04032038,-0.061676636,0.03983965,-0.020327022,-0.012927831,-0.031518564,-0.045263443,0.0030548794,-0.08787462,-0.022514407,-0.094760306,-0.06777074,-0.034546018,0.02785831,0.08785604,-0.058988187,0.03186556,-0.031158632,0.02610723,0.04172636,0.030326573,-0.028129177,0.005538327,-0.0568401,-0.01892591,-0.019030545,-0.07472099,0.049811587,0.032435972,0.0045957565,-0.004332519,-0.07183981,