INSERT INTO public.document_chunks VALUES ('717018a0-0ac7-47fd-b350-f1ba4b8aba78', '4547add7-b0c7-4322-9fc0-4bc59275332e', 36, '• Ví dụ: mật mã AES có kích thước khối là 128 bit
AES-CBC còn an toàn nếu q2*L2/2128 <= 2-80
q2*L2 <= 248 q*L <= 224
Mã tối đa 224 * 16 byte = 228 byte = 256 MB, sau 
đó cần đổi khóa mới.
95
Output Feedback - OFB
96
95
96
50
Tấn công vào mật mã khối
• Tấn công kênh bên (side-channel attack): phán đoán 
giá trịcác bit khóa bằng cách ước lượng thời gian, 
lượng điện năng tiêu thụ, bức xạđiện từ… khi mã hóa, 
giải mã
• Ví dụ: phương pháp tấn công DES của Kocher và Jaffe năm 
1998', '[-0.033272203,0.06285108,-0.062918946,-0.08909434,-0.06542977,0.011493424,0.029975269,0.031305797,0.026621642,0.040737316,0.04853159,-0.06543294,0.011215644,-0.048409592,-0.035758354,-0.0626821,-0.051491383,-0.024994943,-0.05111194,-0.03102925,0.008590404,-0.003986588,-0.052050743,-0.05215544,-0.006522474,0.042100888,-0.004100804,0.07144157,-0.009282665,-0.1193054,0.013083872,0.13893333,0.041323323,-0.047897246,-0.0033721516,0.0154794,0.001234568,-0.09817112,0.023201121,0.0333553,-0.06739385,0.025753755,0.0150414985,-0.04118007,0.048870556,0.042834282,-0.0008941779,0.021241423,-0.022633158,-0.040277958,-0.04540286,0.10915145,0.009886543,0.1177132,-0.062858365,-0.098470815,-0.097893916,0.08681234,0.011707668,0.0105535425,-0.029863534,0.05187807,-0.049743082,0.03160966,-0.0014225108,-0.007005801,0.028444435,-0.020730833,-0.041921284,0.012614188,-0.09291777,-0.012156029,-0.07652719,0.06808429,0.017902639,0.025852647,0.006568451,0.009583665,0.00019194678,-0.09959368,0.051574435,-0.053096373,0.0230617,-0.04939592,0.01104931,0.047242206,0.0013011273,0.020075154,0.06479761,-0.020406865,0.029686142,0.07114752,0.07229837,0.05720171,0.048748914,-0.01956465,0.049715772,0.0261911,-0.05947038,0.04789285,0.06311439,0.0047324263,-0.052496362,-0.030625168,-0.07935823,-0.031117013,0.07351168,0.024046402,0.0014963247,0.0017680543,-0.026851565,0.0149989985,-0.0039032283,-0.16275427,0.047944043,0.012259253,-0.033295177,0.011600651,-0.060556743,0.028285181,0.029844038,-0.12753919,-0.077969015,0.05354164,-0.03701751,0.0056287628,0.037024453,2.1137723e-32,-0.031628966,0.047677632,-0.090997785,-0.015196044,-0.020018898,-0.0025132424,-0.014986924,-0.03421036,-0.083854295,-0.05535565,-0.084926106,-0.024644736,-0.05971447,0.015469779,0.05762643,-0.009434695,0.022449853,-0.08846676,-0.027250659,0.03702217,0.025133608,0.0009128574,0.024729015,-0.025348641,0.041698623,0.06005112,0.0055711633,-0.06701293,-0.028128996,0.03580852,0.029520586,-0.03968878,-0.03155929,-0.08135603,-0.07093513,0