INSERT INTO public.questions VALUES (1, 1, 'Trong lĩnh vực mật mã học, mục tiêu chính của ''xác thực thông điệp'' là gì?', '"[{\"key\": \"a\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh b\\u00ed m\\u1eadt c\\u1ee7a n\\u1ed9i dung th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"b\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh to\\u00e0n v\\u1eb9n v\\u00e0 ngu\\u1ed3n g\\u1ed1c tin c\\u1eady c\\u1ee7a th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"c\", \"text\": \"T\\u0103ng t\\u1ed1c \\u0111\\u1ed9 truy\\u1ec1n t\\u1ea3i th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"d\", \"text\": \"Gi\\u1ea3m k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a th\\u00f4ng \\u0111i\\u1ec7p.\"}]"', 'b', 'Xác thực thông điệp (Message Authentication) tập trung vào việc đảm bảo rằng thông điệp không bị sửa đổi (tính toàn vẹn) và đến từ nguồn gốc tin cậy (tính xác thực nguồn gốc).');
INSERT INTO public.questions VALUES (2, 1, 'Kẻ tấn công chặn một thông điệp, thay đổi nội dung của nó và sau đó chuyển tiếp cho người nhận. Đây là dạng tấn công nào?', '"[{\"key\": \"a\", \"text\": \"T\\u1ea5n c\\u00f4ng gi\\u1ea3 danh (Masquerade attack)\"}, {\"key\": \"b\", \"text\": \"T\\u1ea5n c\\u00f4ng thay th\\u1ebf (Substitution attack)\"}, {\"key\": \"c\", \"text\": \"T\\u1ea5n c\\u00f4ng ph\\u1ee7 nh\\u1eadn g\\u1eedi (Repudiation attack)\"}, {\"key\": \"d\", \"text\": \"T\\u1ea5n c\\u00f4ng ph\\u00e1t l\\u1ea1i (Replay attack)\"}]"', 'b', 'Tấn công thay thế (Substitution attack) mô tả chính xác hành động chặn, thay đổi nội dung và chuyển tiếp thông điệp.');
INSERT INTO public.questions VALUES (3, 1, 'Mã xác thực thông điệp (MAC) được tạo ra như thế nào?', '"[{\"key\": \"a\", \"text\": \"S\\u1eed d\\u1ee5ng kh\\u00f3a c\\u00f4ng khai \\u0111\\u1ec3 m\\u00e3 h\\u00f3a th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"b\", \"text\": \"S\\u1eed d\\u1ee5ng m\\u1ed9t h\\u00e0m b\\u0103m kh\\u00f4ng \\u0111\\u1ed1i x\\u1ee9ng tr\\u00ean th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"c\", \"text\": \"S\\u1eed d\\u1ee5ng m\\u1ed9t h\\u00e0m b\\u00ed m\\u1eadt (S) k\\u1ebft h\\u1ee3p v\\u1edbi kh\\u00f3a b\\u00ed m\\u1eadt (k) v\\u00e0 th\\u00f4ng \\u0111i\\u1ec7p (m) \\u0111\\u1ec3 t\\u1ea1o ra m\\u00e3 t = S(k, m).\"}, {\"key\": \"d\", \"text\": \"Ch\\u1ec9 \\u0111\\u01a1n gi\\u1ea3n l\\u00e0 b\\u0103m th\\u00f4ng \\u0111i\\u1ec7p b\\u1eb1ng m\\u1ed9t h\\u00e0m b\\u0103m c\\u00f4ng khai.\"}]"', 'c', 'MAC được tạo ra bằng cách sử dụng một hàm bí mật (S) kết hợp với một khóa bí mật (k) và thông điệp (m). Đầu ra (t) có kích thước cố định.');
INSERT INTO public.questions VALUES (4, 1, 'Đặc tính nào sau đây KHÔNG phải là đặc tính của một hàm MAC an toàn?', '"[{\"key\": \"a\", \"text\": \"T\\u00ednh x\\u00e1c \\u0111\\u1ecbnh (Deterministic)\"}, {\"key\": \"b\", \"text\": \"T\\u00ednh \\u0111\\u00fang \\u0111\\u1eafn (Correctness)\"}, {\"key\": \"c\", \"text\": \"T\\u00ednh hi\\u1ec7u qu\\u1ea3 (Efficiency)\"}, {\"key\": \"d\", \"text\": \"T\\u00ednh ch\\u1ed1ng t\\u1eeb ch\\u1ed1i (Non-repudiation)\"}]"', 'd', 'MAC cung cấp tính toàn vẹn và xác thực nguồn gốc, nhưng không cung cấp khả năng chống từ chối. Điều này có nghĩa là người gửi có thể phủ nhận việc đã gửi thông điệp.');
INSERT INTO public.questions VALUES (5, 1, 'CBC-MAC là một phương pháp xây dựng MAC. Vấn đề tiềm ẩn của ''rawCBC'' (CBC-MAC không có padding đặc biệt) là gì?', '"[{\"key\": \"a\", \"text\": \"N\\u00f3 kh\\u00f4ng th\\u1ec3 x\\u1eed l\\u00fd c\\u00e1c th\\u00f4ng \\u0111i\\u1ec7p c\\u00f3 \\u0111\\u1ed9 d\\u00e0i l\\u1edbn.\"}, {\"key\": \"b\", \"text\": \"N\\u00f3 d\\u1ec5 b\\u1ecb t\\u1ea5n c\\u00f4ng ch\\u1ecdn tr\\u01b0\\u1edbc b\\u1ea3n r\\u00f5 (chosen-plaintext attack).\"}, {\"key\": \"c\", \"text\": \"N\\u00f3 kh\\u00f4ng cung c\\u1ea5p t\\u00ednh to\\u00e0n v\\u1eb9n cho th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"d\", \"text\": \"N\\u00f3 y\\u00eau c\\u1ea7u kh\\u00f3a c\\u00f3 k\\u00edch th\\u01b0\\u1edbc r\\u1ea5t l\\u1edbn.\"}]"', 'b', 'RawCBC dễ bị tấn công chọn trước bản rõ vì kẻ tấn công có thể tạo ra một bản rõ mới mà mã MAC của nó có thể được tính toán dựa trên mã MAC của bản rõ ban đầu và một phần của bản rõ mới.');
INSERT INTO public.questions VALUES (6, 1, 'Tấn công phát lại (Replay attack) xảy ra khi nào?', '"[{\"key\": \"a\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng thay \\u0111\\u1ed5i n\\u1ed9i dung c\\u1ee7a th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"b\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng m\\u1ea1o danh m\\u1ed9t b\\u00ean g\\u1eedi th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"c\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng ph\\u00e1t l\\u1ea1i m\\u1ed9t b\\u1ea3n tin \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c ch\\u1ee9ng th\\u1ef1c trong m\\u1ed9t phi\\u00ean truy\\u1ec1n th\\u00f4ng tr\\u01b0\\u1edbc \\u0111\\u00f3.\"}, {\"key\": \"d\", \"text\": \"Ng\\u01b0\\u1eddi g\\u1eedi ph\\u1ee7 nh\\u1eadn vi\\u1ec7c \\u0111\\u00e3 g\\u1eedi m\\u1ed9t th\\u00f4ng tin.\"}]"', 'c', 'Tấn công phát lại là khi kẻ tấn công gửi lại một bản tin đã được xác thực trước đó, thường là để lặp lại một hành động hoặc lợi dụng một giao dịch đã được thực hiện.');
INSERT INTO public.questions VALUES (7, 1, 'Mật mã có xác thực (Authenticated Encryption) cung cấp những dịch vụ nào?', '"[{\"key\": \"a\", \"text\": \"Ch\\u1ec9 t\\u00ednh b\\u00ed m\\u1eadt.\"}, {\"key\": \"b\", \"text\": \"Ch\\u1ec9 t\\u00ednh to\\u00e0n v\\u1eb9n v\\u00e0 x\\u00e1c th\\u1ef1c.\"}, {\"key\": \"c\", \"text\": \"T\\u00ednh b\\u00ed m\\u1eadt, t\\u00ednh to\\u00e0n v\\u1eb9n v\\u00e0 t\\u00ednh x\\u00e1c th\\u1ef1c.\"}, {\"key\": \"d\", \"text\": \"Ch\\u1ec9 t\\u00ednh ch\\u1ed1ng t\\u1eeb ch\\u1ed1i.\"}]"', 'c', 'Mật mã có xác thực (Authenticated Encryption - AE) kết hợp cả hai chức năng: mã hóa để đảm bảo tính bí mật và MAC để đảm bảo tính toàn vẹn và xác thực.');
INSERT INTO public.questions VALUES (8, 1, 'Trong các sơ đồ MAC-then-encrypt, Encrypt-and-MAC, và Encrypt-then-MAC, sơ đồ nào được coi là an toàn nhất và chống lại tấn công CCA (Chosen Ciphertext Attack)?', '"[{\"key\": \"a\", \"text\": \"MAC-then-encrypt\"}, {\"key\": \"b\", \"text\": \"Encrypt-and-MAC\"}, {\"key\": \"c\", \"text\": \"Encrypt-then-MAC\"}, {\"key\": \"d\", \"text\": \"T\\u1ea5t c\\u1ea3 \\u0111\\u1ec1u an to\\u00e0n nh\\u01b0 nhau.\"}]"', 'c', 'Encrypt-then-MAC là sơ đồ an toàn nhất vì nó xác thực tính toàn vẹn của bản mã trước khi giải mã, do đó ngăn chặn hiệu quả các tấn công CCA.');
INSERT INTO public.questions VALUES (9, 1, 'Hàm băm mật mã có đặc tính ''tính một chiều'' (one-way property) nghĩa là gì?', '"[{\"key\": \"a\", \"text\": \"R\\u1ea5t d\\u1ec5 d\\u00e0ng \\u0111\\u1ec3 t\\u00ednh to\\u00e1n gi\\u00e1 tr\\u1ecb b\\u0103m t\\u1eeb b\\u1ea3n tin g\\u1ed1c.\"}, {\"key\": \"b\", \"text\": \"R\\u1ea5t kh\\u00f3 \\u0111\\u1ec3 t\\u00ecm ra b\\u1ea3n tin g\\u1ed1c khi ch\\u1ec9 bi\\u1ebft gi\\u00e1 tr\\u1ecb b\\u0103m.\"}, {\"key\": \"c\", \"text\": \"Hai b\\u1ea3n tin kh\\u00e1c nhau lu\\u00f4n c\\u00f3 gi\\u00e1 tr\\u1ecb b\\u0103m kh\\u00e1c nhau.\"}, {\"key\": \"d\", \"text\": \"Gi\\u00e1 tr\\u1ecb b\\u0103m lu\\u00f4n c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh, b\\u1ea5t k\\u1ec3 \\u0111\\u1ed9 d\\u00e0i b\\u1ea3n tin.\"}]"', 'b', 'Tính một chiều của hàm băm mật mã có nghĩa là việc tính toán ngược từ giá trị băm để tìm ra bản tin gốc là cực kỳ khó khăn về mặt tính toán.');
INSERT INTO public.questions VALUES (10, 1, 'Tấn công dựa trên Nghịch lý ngày sinh (Birthday Paradox Attack) nhằm mục đích gì trong việc tấn công hàm băm?', '"[{\"key\": \"a\", \"text\": \"T\\u00ecm ra b\\u1ea3n tin g\\u1ed1c t\\u1eeb gi\\u00e1 tr\\u1ecb b\\u0103m \\u0111\\u00e3 cho.\"}, {\"key\": \"b\", \"text\": \"T\\u00ecm ra hai b\\u1ea3n tin kh\\u00e1c nhau c\\u00f3 c\\u00f9ng gi\\u00e1 tr\\u1ecb b\\u0103m (collision).\"}, {\"key\": \"c\", \"text\": \"D\\u1ef1 \\u0111o\\u00e1n gi\\u00e1 tr\\u1ecb b\\u0103m c\\u1ee7a m\\u1ed9t b\\u1ea3n tin ch\\u01b0a bi\\u1ebft.\"}, {\"key\": \"d\", \"text\": \"T\\u0103ng k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a gi\\u00e1 tr\\u1ecb b\\u0103m.\"}]"', 'b', 'Tấn công ngày sinh khai thác xác suất cao hơn để tìm ra hai đầu vào khác nhau tạo ra cùng một đầu ra (đụng độ - collision) trong một hàm băm, so với việc tìm một đầu vào cụ thể cho một đầu ra đã biết.');
INSERT INTO public.questions VALUES (11, 2, 'Mục tiêu chính của mật mã là gì?', '"[{\"key\": \"A\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh s\\u1eb5n s\\u00e0ng c\\u1ee7a th\\u00f4ng tin.\"}, {\"key\": \"B\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh b\\u00ed m\\u1eadt, to\\u00e0n v\\u1eb9n v\\u00e0 x\\u00e1c th\\u1ef1c c\\u1ee7a th\\u00f4ng tin.\"}, {\"key\": \"C\", \"text\": \"T\\u0103ng t\\u1ed1c \\u0111\\u1ed9 truy\\u1ec1n d\\u1eef li\\u1ec7u.\"}, {\"key\": \"D\", \"text\": \"Gi\\u1ea3m dung l\\u01b0\\u1ee3ng l\\u01b0u tr\\u1eef d\\u1eef li\\u1ec7u.\"}]"', 'B', 'Mục tiêu của mật mã bao gồm tính bí mật (Confidentiality), tính toàn vẹn (Integrity) và tính xác thực (Authenticity).');
INSERT INTO public.questions VALUES (12, 2, 'Trong mật mã học, ''plaintext'' (bản rõ) là gì?', '"[{\"key\": \"A\", \"text\": \"Th\\u00f4ng tin \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c m\\u00e3 h\\u00f3a.\"}, {\"key\": \"B\", \"text\": \"Kh\\u00f3a b\\u00ed m\\u1eadt d\\u00f9ng \\u0111\\u1ec3 m\\u00e3 h\\u00f3a.\"}, {\"key\": \"C\", \"text\": \"Th\\u00f4ng tin g\\u1ed1c, ch\\u01b0a \\u0111\\u01b0\\u1ee3c m\\u00e3 h\\u00f3a.\"}, {\"key\": \"D\", \"text\": \"Thu\\u1eadt to\\u00e1n d\\u00f9ng \\u0111\\u1ec3 gi\\u1ea3i m\\u00e3.\"}]"', 'C', 'Plaintext (bản rõ) là thông tin gốc, chưa được mã hóa, trước khi nó được biến đổi thành dạng mã hóa (ciphertext).');
INSERT INTO public.questions VALUES (13, 2, 'Mật mã Caesar là một ví dụ của loại hình mật mã nào?', '"[{\"key\": \"A\", \"text\": \"M\\u1eadt m\\u00e3 ho\\u00e1n v\\u1ecb.\"}, {\"key\": \"B\", \"text\": \"M\\u1eadt m\\u00e3 thay th\\u1ebf \\u0111\\u01a1n gi\\u1ea3n.\"}, {\"key\": \"C\", \"text\": \"M\\u1eadt m\\u00e3 \\u0111a b\\u1ea3ng th\\u1ebf.\"}, {\"key\": \"D\", \"text\": \"M\\u1eadt m\\u00e3 d\\u00f2ng.\"}]"', 'B', 'Mật mã Caesar thay thế mỗi ký tự trong bản rõ bằng một ký tự khác đứng sau nó một số vị trí cố định trong bảng chữ cái, đây là một dạng của mật mã thay thế đơn giản.');
INSERT INTO public.questions VALUES (14, 2, 'Nguyên lý Kerckhoffs khẳng định rằng một hệ mật mã cần phải an toàn ngay cả khi đối phương biết mọi thông tin về hệ, ngoại trừ yếu tố nào?', '"[{\"key\": \"A\", \"text\": \"Thu\\u1eadt to\\u00e1n m\\u00e3 h\\u00f3a.\"}, {\"key\": \"B\", \"text\": \"Thi\\u1ebft k\\u1ebf c\\u1ee7a h\\u1ec7 th\\u1ed1ng.\"}, {\"key\": \"C\", \"text\": \"Kh\\u00f3a b\\u00ed m\\u1eadt.\"}, {\"key\": \"D\", \"text\": \"C\\u1ea5u tr\\u00fac c\\u1ee7a b\\u1ea3n r\\u00f5.\"}]"', 'C', 'Nguyên lý Kerckhoffs (Nguyên lý thứ 2) cho rằng sự an toàn của hệ mật mã chỉ nên phụ thuộc vào tính bí mật của khóa, không phụ thuộc vào bí mật của thuật toán.');
INSERT INTO public.questions VALUES (15, 2, 'Hệ mật mã nào được coi là ''hoàn hảo'' theo lý thuyết Shannon, nghĩa là bản mã không chứa bất kỳ thông tin nào về bản rõ nếu khóa hoàn toàn ngẫu nhiên và chỉ sử dụng một lần?', '"[{\"key\": \"A\", \"text\": \"M\\u1eadt m\\u00e3 Caesar.\"}, {\"key\": \"B\", \"text\": \"M\\u1eadt m\\u00e3 Vigen\\u00e8re.\"}, {\"key\": \"C\", \"text\": \"M\\u1eadt m\\u00e3 DES.\"}, {\"key\": \"D\", \"text\": \"M\\u1eadt m\\u00e3 One-Time Pad (OTP).\"}]"', 'D', 'Mật mã One-Time Pad (OTP) được chứng minh là hệ mật mã hoàn hảo nếu khóa ngẫu nhiên, chỉ dùng một lần và có độ dài bằng bản rõ.');
INSERT INTO public.questions VALUES (16, 2, 'Trong mật mã khóa đối xứng (Symmetric Cryptography), điều gì là đúng?', '"[{\"key\": \"A\", \"text\": \"Kh\\u00f3a m\\u00e3 h\\u00f3a v\\u00e0 kh\\u00f3a gi\\u1ea3i m\\u00e3 l\\u00e0 kh\\u00e1c nhau.\"}, {\"key\": \"B\", \"text\": \"C\\u1ea7n c\\u00f3 m\\u1ed9t k\\u00eanh b\\u00ed m\\u1eadt \\u0111\\u1ec3 chia s\\u1ebb kh\\u00f3a.\"}, {\"key\": \"C\", \"text\": \"Ch\\u1ec9 c\\u00f3 th\\u1ec3 s\\u1eed d\\u1ee5ng cho c\\u00e1c b\\u1ea3n tin ng\\u1eafn.\"}, {\"key\": \"D\", \"text\": \"T\\u1ed1c \\u0111\\u1ed9 m\\u00e3 h\\u00f3a v\\u00e0 gi\\u1ea3i m\\u00e3 ch\\u1eadm.\"}]"', 'B', 'Trong mật mã khóa đối xứng, cùng một khóa được sử dụng cho cả mã hóa và giải mã, do đó việc chia sẻ khóa này một cách bí mật giữa các bên là yêu cầu bắt buộc.');
INSERT INTO public.questions VALUES (17, 2, 'Loại tấn công nào mà kẻ tấn công có quyền truy cập vào một số cặp bản rõ và bản mã tương ứng, với mục đích xác định khóa bí mật hoặc giải mã các bản mã khác?', '"[{\"key\": \"A\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ec9 bi\\u1ebft b\\u1ea3n m\\u1eadt (Ciphertext-Only Attack).\"}, {\"key\": \"B\", \"text\": \"T\\u1ea5n c\\u00f4ng bi\\u1ebft tr\\u01b0\\u1edbc b\\u1ea3n r\\u00f5 (Known-Plaintext Attack - KPA).\"}, {\"key\": \"C\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ecdn tr\\u01b0\\u1edbc b\\u1ea3n m\\u1eadt (Chosen-Plaintext Attack - CPA).\"}, {\"key\": \"D\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ecdn tr\\u01b0\\u1edbc b\\u1ea3n m\\u00e3 (Chosen-Ciphertext Attack - CCA).\"}]"', 'B', 'Known-Plaintext Attack (KPA) là loại tấn công mà kẻ tấn công có sẵn các cặp bản rõ và bản mã tương ứng được tạo ra bởi cùng một khóa.');
INSERT INTO public.questions VALUES (18, 2, 'Mật mã khối (Block Cipher) xử lý dữ liệu theo cách nào?', '"[{\"key\": \"A\", \"text\": \"X\\u1eed l\\u00fd t\\u1eebng k\\u00fd t\\u1ef1 m\\u1ed9t.\"}, {\"key\": \"B\", \"text\": \"X\\u1eed l\\u00fd t\\u1eebng kh\\u1ed1i d\\u1eef li\\u1ec7u c\\u00f3 k\\u00edch th\\u01b0\\u1edbc c\\u1ed1 \\u0111\\u1ecbnh.\"}, {\"key\": \"C\", \"text\": \"X\\u1eed l\\u00fd d\\u1eef li\\u1ec7u theo lu\\u1ed3ng th\\u1eddi gian th\\u1ef1c.\"}, {\"key\": \"D\", \"text\": \"M\\u00e3 h\\u00f3a to\\u00e0n b\\u1ed9 b\\u1ea3n tin th\\u00e0nh m\\u1ed9t kh\\u1ed1i duy nh\\u1ea5t.\"}]"', 'B', 'Mật mã khối (Block Cipher) hoạt động bằng cách chia dữ liệu đầu vào thành các khối có kích thước cố định và mã hóa từng khối một.');
INSERT INTO public.questions VALUES (19, 2, 'Trong mật mã khóa bất đối xứng (Asymmetric Cryptography), điều gì là đúng?', '"[{\"key\": \"A\", \"text\": \"Kh\\u00f3a m\\u00e3 h\\u00f3a v\\u00e0 kh\\u00f3a gi\\u1ea3i m\\u00e3 gi\\u1ed1ng nhau.\"}, {\"key\": \"B\", \"text\": \"An to\\u00e0n d\\u1ef1a tr\\u00ean c\\u00e1c b\\u00e0i to\\u00e1n kh\\u00f3 v\\u1ec1 m\\u1eb7t t\\u00ednh to\\u00e1n.\"}, {\"key\": \"C\", \"text\": \"Kh\\u00f4ng c\\u1ea7n chia s\\u1ebb kh\\u00f3a gi\\u1eefa c\\u00e1c b\\u00ean.\"}, {\"key\": \"D\", \"text\": \"T\\u1ed1c \\u0111\\u1ed9 m\\u00e3 h\\u00f3a v\\u00e0 gi\\u1ea3i m\\u00e3 nhanh h\\u01a1n m\\u1eadt m\\u00e3 kh\\u00f3a \\u0111\\u1ed1i x\\u1ee9ng.\"}]"', 'B', 'Mật mã khóa bất đối xứng (hay mật mã khóa công khai) dựa trên các bài toán toán học khó giải quyết trong thời gian đa thức, ví dụ như phân tích số nguyên tố, để đảm bảo an toàn.');
INSERT INTO public.questions VALUES (20, 2, 'Chế độ hoạt động nào của mật mã khối (Block Cipher) được khuyến cáo KHÔNG sử dụng vì nó không chống lại được tấn công KPA và có thể làm lộ thông tin nếu các khối bản rõ giống nhau?', '"[{\"key\": \"A\", \"text\": \"CBC (Cipher Block Chaining).\"}, {\"key\": \"B\", \"text\": \"CTR (Counter Mode).\"}, {\"key\": \"C\", \"text\": \"ECB (Electronic Code Book).\"}, {\"key\": \"D\", \"text\": \"OFB (Output Feedback).\"}]"', 'C', 'Chế độ ECB mã hóa mỗi khối bản rõ một cách độc lập, do đó nếu hai khối bản rõ giống nhau thì hai khối bản mã cũng sẽ giống nhau, làm lộ thông tin và không chống lại được tấn công KPA.');
INSERT INTO public.questions VALUES (21, 3, 'Mục tiêu chính của việc xác thực thông điệp là gì?', '"[{\"key\": \"a\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh b\\u00ed m\\u1eadt c\\u1ee7a th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"b\", \"text\": \"X\\u00e1c minh r\\u1eb1ng n\\u1ed9i dung th\\u00f4ng \\u0111i\\u1ec7p kh\\u00f4ng b\\u1ecb s\\u1eeda \\u0111\\u1ed5i v\\u00e0 ngu\\u1ed3n g\\u1ed1c l\\u00e0 \\u0111\\u00e1ng tin c\\u1eady.\"}, {\"key\": \"c\", \"text\": \"T\\u0103ng t\\u1ed1c \\u0111\\u1ed9 truy\\u1ec1n th\\u00f4ng \\u0111i\\u1ec7p.\"}, {\"key\": \"d\", \"text\": \"Gi\\u1ea3m k\\u00edch th\\u01b0\\u1edbc c\\u1ee7a th\\u00f4ng \\u0111i\\u1ec7p.\"}]"', 'b', 'Xác thực thông điệp tập trung vào việc đảm bảo tính toàn vẹn (không bị sửa đổi) và nguồn gốc tin cậy (không bị giả mạo hoặc phủ nhận) của thông điệp.');
INSERT INTO public.questions VALUES (22, 3, 'Trong các dạng tấn công điển hình vào tính xác thực, tấn công nào mô tả việc kẻ tấn công chặn thông điệp, thay đổi nội dung và chuyển tiếp cho bên kia?', '"[{\"key\": \"a\", \"text\": \"T\\u1ea5n c\\u00f4ng gi\\u1ea3 danh (Masquerade)\"}, {\"key\": \"b\", \"text\": \"T\\u1ea5n c\\u00f4ng ph\\u1ee7 nh\\u1eadn (Repudiation)\"}, {\"key\": \"c\", \"text\": \"T\\u1ea5n c\\u00f4ng thay th\\u1ebf (Substitution)\"}, {\"key\": \"d\", \"text\": \"T\\u1ea5n c\\u00f4ng ph\\u00e1t l\\u1ea1i (Replay attack)\"}]"', 'c', 'Tấn công thay thế (Substitution) là hành động chặn, thay đổi nội dung và chuyển tiếp thông điệp.');
INSERT INTO public.questions VALUES (23, 3, 'Mã xác thực thông điệp (MAC) được tạo ra như thế nào?', '"[{\"key\": \"a\", \"text\": \"S\\u1eed d\\u1ee5ng h\\u00e0m b\\u0103m kh\\u00f4ng kh\\u00f3a.\"}, {\"key\": \"b\", \"text\": \"S\\u1eed d\\u1ee5ng m\\u1ed9t h\\u00e0m b\\u00ed m\\u1eadt S k\\u1ebft h\\u1ee3p v\\u1edbi kh\\u00f3a b\\u00ed m\\u1eadt k v\\u00e0 b\\u1ea3n tin m \\u0111\\u1ec3 t\\u1ea1o ra m\\u00e3 t = S(k, m).\"}, {\"key\": \"c\", \"text\": \"M\\u00e3 h\\u00f3a b\\u1ea3n tin b\\u1eb1ng kh\\u00f3a c\\u00f4ng khai.\"}, {\"key\": \"d\", \"text\": \"Ch\\u1ec9 \\u0111\\u01a1n gi\\u1ea3n l\\u00e0 b\\u0103m b\\u1ea3n tin.\"}]"', 'b', 'MAC được tạo ra bằng cách sử dụng một hàm bí mật S, một khóa bí mật k và bản tin m, theo công thức t = S(k, m).');
INSERT INTO public.questions VALUES (24, 3, 'Đặc tính nào của MAC đảm bảo rằng nếu hai bản tin giống nhau thì mã MAC của chúng cũng sẽ giống nhau?', '"[{\"key\": \"a\", \"text\": \"T\\u00ednh \\u0111\\u00fang \\u0111\\u1eafn\"}, {\"key\": \"b\", \"text\": \"T\\u00ednh hi\\u1ec7u qu\\u1ea3\"}, {\"key\": \"c\", \"text\": \"T\\u00ednh x\\u00e1c \\u0111\\u1ecbnh\"}, {\"key\": \"d\", \"text\": \"T\\u00ednh an to\\u00e0n\"}]"', 'c', 'Tính xác định (Deterministic) của MAC có nghĩa là với cùng một khóa và cùng một bản tin đầu vào, đầu ra (mã MAC) luôn giống nhau.');
INSERT INTO public.questions VALUES (25, 3, 'MAC cung cấp những dịch vụ nào sau đây?', '"[{\"key\": \"a\", \"text\": \"To\\u00e0n v\\u1eb9n, x\\u00e1c th\\u1ef1c danh t\\u00ednh, ch\\u1ed1ng t\\u1eeb ch\\u1ed1i, gi\\u1eef b\\u00ed m\\u1eadt.\"}, {\"key\": \"b\", \"text\": \"To\\u00e0n v\\u1eb9n, x\\u00e1c th\\u1ef1c danh t\\u00ednh, ch\\u1ed1ng t\\u1eeb ch\\u1ed1i.\"}, {\"key\": \"c\", \"text\": \"To\\u00e0n v\\u1eb9n, x\\u00e1c th\\u1ef1c danh t\\u00ednh.\"}, {\"key\": \"d\", \"text\": \"Ch\\u1ec9 to\\u00e0n v\\u1eb9n.\"}]"', 'c', 'MAC cung cấp tính toàn vẹn và xác thực danh tính, nhưng không cung cấp khả năng chống từ chối (vì cả hai bên đều biết khóa) và không giữ bí mật thông điệp.');
INSERT INTO public.questions VALUES (26, 3, 'Kiến trúc CBC-MAC có vấn đề gì với tấn công chọn trước bản rõ (chosen-plaintext attack)?', '"[{\"key\": \"a\", \"text\": \"N\\u00f3 kh\\u00f4ng th\\u1ec3 x\\u1eed l\\u00fd c\\u00e1c b\\u1ea3n tin c\\u00f3 \\u0111\\u1ed9 d\\u00e0i kh\\u00e1c nhau.\"}, {\"key\": \"b\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng c\\u00f3 th\\u1ec3 t\\u1ea1o ra m\\u1ed9t b\\u1ea3n tin m\\u1edbi c\\u00f3 m\\u00e3 MAC gi\\u1ed1ng v\\u1edbi b\\u1ea3n tin g\\u1ed1c b\\u1eb1ng c\\u00e1ch s\\u1eed d\\u1ee5ng th\\u00f4ng tin t\\u1eeb b\\u1ea3n tin g\\u1ed1c v\\u00e0 m\\u00e3 h\\u00f3a.\"}, {\"key\": \"c\", \"text\": \"N\\u00f3 y\\u00eau c\\u1ea7u kh\\u00f3a ph\\u1ea3i \\u0111\\u01b0\\u1ee3c thay \\u0111\\u1ed5i li\\u00ean t\\u1ee5c.\"}, {\"key\": \"d\", \"text\": \"N\\u00f3 kh\\u00f4ng th\\u1ec3 ph\\u00e1t hi\\u1ec7n c\\u00e1c thay \\u0111\\u1ed5i nh\\u1ecf trong b\\u1ea3n tin.\"}]"', 'b', 'Kiến trúc raw CBC-MAC dễ bị tấn công chọn trước bản rõ, nơi kẻ tấn công có thể lợi dụng cấu trúc để tạo ra một bản tin mới có mã MAC hợp lệ.');
INSERT INTO public.questions VALUES (27, 3, 'Tấn công phát lại (Replay attack) xảy ra khi nào?', '"[{\"key\": \"a\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng thay \\u0111\\u1ed5i n\\u1ed9i dung c\\u1ee7a b\\u1ea3n tin.\"}, {\"key\": \"b\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng gi\\u1ea3 m\\u1ea1o danh t\\u00ednh c\\u1ee7a ng\\u01b0\\u1eddi g\\u1eedi.\"}, {\"key\": \"c\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng ph\\u00e1t l\\u1ea1i m\\u1ed9t b\\u1ea3n tin \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c ch\\u1ee9ng th\\u1ef1c trong m\\u1ed9t phi\\u00ean truy\\u1ec1n th\\u00f4ng tr\\u01b0\\u1edbc \\u0111\\u00f3.\"}, {\"key\": \"d\", \"text\": \"K\\u1ebb t\\u1ea5n c\\u00f4ng c\\u1ed1 g\\u1eafng \\u0111o\\u00e1n kh\\u00f3a b\\u00ed m\\u1eadt.\"}]"', 'c', 'Tấn công phát lại là việc kẻ tấn công sử dụng lại một bản tin đã được gửi và xác thực trước đó, thường là để thực hiện lại một hành động (ví dụ: chuyển tiền).');
INSERT INTO public.questions VALUES (28, 3, 'Mật mã có xác thực (Authenticated Encryption) cung cấp những tính năng gì?', '"[{\"key\": \"a\", \"text\": \"Ch\\u1ec9 t\\u00ednh b\\u00ed m\\u1eadt.\"}, {\"key\": \"b\", \"text\": \"Ch\\u1ec9 t\\u00ednh to\\u00e0n v\\u1eb9n.\"}, {\"key\": \"c\", \"text\": \"\\u0110\\u1ed3ng th\\u1eddi t\\u00ednh b\\u00ed m\\u1eadt v\\u00e0 t\\u00ednh to\\u00e0n v\\u1eb9n.\"}, {\"key\": \"d\", \"text\": \"Ch\\u1ec9 t\\u00ednh x\\u00e1c th\\u1ef1c danh t\\u00ednh.\"}]"', 'c', 'Mật mã có xác thực (AE) kết hợp cả hai tính năng: tính bí mật (encryption) và tính toàn vẹn (authentication).');
INSERT INTO public.questions VALUES (29, 3, 'Trong các sơ đồ Mật mã có xác thực, sơ đồ nào được coi là an toàn nhất và đảm bảo chống lại tấn công CCA (Chosen-Ciphertext Attack)?', '"[{\"key\": \"a\", \"text\": \"MAC-then-encrypt\"}, {\"key\": \"b\", \"text\": \"Encrypt-and-MAC\"}, {\"key\": \"c\", \"text\": \"Encrypt-then-MAC\"}, {\"key\": \"d\", \"text\": \"T\\u1ea5t c\\u1ea3 c\\u00e1c s\\u01a1 \\u0111\\u1ed3 tr\\u00ean \\u0111\\u1ec1u an to\\u00e0n nh\\u01b0 nhau.\"}]"', 'c', 'Sơ đồ Encrypt-then-MAC (như IPSec) được coi là an toàn nhất vì nó xác thực tính toàn vẹn của cả bản rõ và bản mã, đồng thời MAC không chứa thông tin về bản rõ, giúp chống lại tấn công CCA.');
INSERT INTO public.questions VALUES (30, 3, 'Đặc tính nào của hàm băm mật mã đảm bảo rằng không thể tìm ra bản tin gốc từ mã băm đã cho?', '"[{\"key\": \"a\", \"text\": \"T\\u00ednh \\u0111\\u00fang \\u0111\\u1eafn\"}, {\"key\": \"b\", \"text\": \"T\\u00ednh hi\\u1ec7u qu\\u1ea3\"}, {\"key\": \"c\", \"text\": \"T\\u00ednh m\\u1ed9t chi\\u1ec1u (One-way)\"}, {\"key\": \"d\", \"text\": \"T\\u00ednh ch\\u1ed1ng \\u0111\\u1ee5ng \\u0111\\u1ed9\"}]"', 'c', 'Tính một chiều (One-way property) của hàm băm mật mã có nghĩa là rất khó hoặc không thể tính toán ngược lại bản tin gốc từ mã băm của nó.');
INSERT INTO public.questions VALUES (31, 4, 'Mục tiêu chính của mật mã là gì?', '"[{\"key\": \"A\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh s\\u1eb5n s\\u00e0ng c\\u1ee7a th\\u00f4ng tin.\"}, {\"key\": \"B\", \"text\": \"\\u0110\\u1ea3m b\\u1ea3o t\\u00ednh b\\u00ed m\\u1eadt c\\u1ee7a th\\u00f4ng tin.\"}, {\"key\": \"C\", \"text\": \"T\\u0103ng t\\u1ed1c \\u0111\\u1ed9 truy\\u1ec1n d\\u1eef li\\u1ec7u.\"}, {\"key\": \"D\", \"text\": \"Gi\\u1ea3m dung l\\u01b0\\u1ee3ng l\\u01b0u tr\\u1eef th\\u00f4ng tin.\"}]"', 'B', 'Tài liệu nêu rõ ''Mục tiêu của mật mã: Tính bí mật (Confidentiality): Đối phương không đọc được bản tin''.');
INSERT INTO public.questions VALUES (32, 4, 'Trong mật mã học, ''Thám mã'' (cryptoanalysis) là gì?', '"[{\"key\": \"A\", \"text\": \"Ng\\u00e0nh khoa h\\u1ecdc nghi\\u00ean c\\u1ee9u c\\u00e1c ph\\u01b0\\u01a1ng ph\\u00e1p to\\u00e1n h\\u1ecdc \\u0111\\u1ec3 m\\u00e3 h\\u00f3a gi\\u1eef b\\u00ed m\\u1eadt th\\u00f4ng tin.\"}, {\"key\": \"B\", \"text\": \"Ng\\u00e0nh khoa h\\u1ecdc nghi\\u00ean c\\u1ee9u c\\u00e1c ph\\u01b0\\u01a1ng ph\\u00e1p to\\u00e1n h\\u1ecdc \\u0111\\u1ec3 ph\\u00e1 v\\u1ee1 h\\u1ec7 m\\u1eadt m\\u00e3.\"}, {\"key\": \"C\", \"text\": \"Ng\\u00e0nh khoa h\\u1ecdc nghi\\u00ean c\\u1ee9u c\\u00e1ch th\\u1ee9c bi\\u1ec3u di\\u1ec5n th\\u00f4ng tin.\"}, {\"key\": \"D\", \"text\": \"Ng\\u00e0nh khoa h\\u1ecdc nghi\\u00ean c\\u1ee9u v\\u1ec1 c\\u00e1c thu\\u1eadt to\\u00e1n m\\u00e3 h\\u00f3a kh\\u00f3a \\u0111\\u1ed1i x\\u1ee9ng.\"}]"', 'B', 'Tài liệu định nghĩa ''Thám mã (cryptoanalysis): nghiên cứu các phương pháp toán học để phá vỡ hệ mật mã''.');
INSERT INTO public.questions VALUES (33, 4, 'Mật mã Caesar là một ví dụ của loại mật mã nào?', '"[{\"key\": \"A\", \"text\": \"M\\u1eadt m\\u00e3 ho\\u00e1n v\\u1ecb.\"}, {\"key\": \"B\", \"text\": \"M\\u1eadt m\\u00e3 thay th\\u1ebf k\\u00fd t\\u1ef1.\"}, {\"key\": \"C\", \"text\": \"M\\u1eadt m\\u00e3 \\u0111a b\\u1ea3ng th\\u1ebf.\"}, {\"key\": \"D\", \"text\": \"M\\u1eadt m\\u00e3 d\\u00f2ng.\"}]"', 'B', 'Tài liệu mô tả mật mã Caesar là ''thay thế một ký tự (bản rõ) trong bảng chữ cái bằng ký tự (bản mật) đứng sau nó 3 vị trí''.');
INSERT INTO public.questions VALUES (34, 4, 'Nguyên tắc Kerckhoffs thứ hai nói rằng thiết kế của hệ mật mã nên là gì?', '"[{\"key\": \"A\", \"text\": \"B\\u00ed m\\u1eadt.\"}, {\"key\": \"B\", \"text\": \"M\\u1edf v\\u00e0 c\\u00f4ng khai.\"}, {\"key\": \"C\", \"text\": \"Ph\\u1ee9c t\\u1ea1p v\\u00e0 kh\\u00f3 hi\\u1ec3u.\"}, {\"key\": \"D\", \"text\": \"Ch\\u1ec9 c\\u00f3 th\\u1ec3 s\\u1eed d\\u1ee5ng b\\u1eb1ng ph\\u1ea7n c\\u1ee9ng chuy\\u00ean d\\u1ee5ng.\"}]"', 'B', 'Nguyên lý Kerckhoffs thứ hai được nêu là ''Thiết kế mở: Không giữ bí mật thiết kế''.');
INSERT INTO public.questions VALUES (35, 4, 'Hệ mật mã Vernam được coi là hoàn hảo về mặt lý thuyết nếu điều kiện nào sau đây được đáp ứng?', '"[{\"key\": \"A\", \"text\": \"Kh\\u00f3a \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng l\\u1eb7p l\\u1ea1i nhi\\u1ec1u l\\u1ea7n.\"}, {\"key\": \"B\", \"text\": \"Kh\\u00f3a ho\\u00e0n to\\u00e0n ng\\u1eabu nhi\\u00ean v\\u00e0 kh\\u00f4ng l\\u1eb7p l\\u1ea1i.\"}, {\"key\": \"C\", \"text\": \"Kh\\u00f3a c\\u00f3 k\\u00edch th\\u01b0\\u1edbc nh\\u1ecf h\\u01a1n b\\u1ea3n r\\u00f5.\"}, {\"key\": \"D\", \"text\": \"Kh\\u00f3a \\u0111\\u01b0\\u1ee3c t\\u1ea1o ra t\\u1eeb m\\u1ed9t m\\u1eadt kh\\u1ea9u \\u0111\\u01a1n gi\\u1ea3n.\"}]"', 'B', 'Tài liệu ghi rõ: ''Trên lý thuyết, hệ mật mã Vernam là hoàn hảo (không thể bị phá vỡ trong mọi điều kiện) nếu khóa hoàn toàn ngẫu nhiên và không lặp lại''.');
INSERT INTO public.questions VALUES (36, 4, 'Mật mã DES (Data Encryption Standard) có kích thước khóa là bao nhiêu bit?', '"[{\"key\": \"A\", \"text\": \"128 bit.\"}, {\"key\": \"B\", \"text\": \"256 bit.\"}, {\"key\": \"C\", \"text\": \"56 bit.\"}, {\"key\": \"D\", \"text\": \"64 bit.\"}]"', 'C', 'Tài liệu nêu rõ: ''Hệ mật mã DES (Data Encryption Standard) ... Kích thước khóa: 56 bit''.');
INSERT INTO public.questions VALUES (37, 4, 'Trong mật mã khóa đối xứng, khóa được sử dụng cho quá trình mã hóa và giải mã có giống nhau hay khác nhau?', '"[{\"key\": \"A\", \"text\": \"Gi\\u1ed1ng nhau.\"}, {\"key\": \"B\", \"text\": \"Kh\\u00e1c nhau.\"}, {\"key\": \"C\", \"text\": \"M\\u1ed9t gi\\u1ed1ng, m\\u1ed9t kh\\u00e1c t\\u00f9y thu\\u1ed9c v\\u00e0o thu\\u1eadt to\\u00e1n.\"}, {\"key\": \"D\", \"text\": \"Kh\\u00f4ng c\\u00f3 kh\\u00f3a n\\u00e0o \\u0111\\u01b0\\u1ee3c s\\u1eed d\\u1ee5ng.\"}]"', 'A', 'Tài liệu định nghĩa: ''Hệ mật mã khóa đối xứng, Secret-key cryptography: sử dụng cùng một khóa khi mã hóa và giải mã''.');
INSERT INTO public.questions VALUES (38, 4, 'Loại tấn công nào mà kẻ tấn công có quyền truy cập không hạn chế vào thành phần mã hóa và có thể lựa chọn các bản rõ để mã hóa?', '"[{\"key\": \"A\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ec9 bi\\u1ebft b\\u1ea3n m\\u1eadt (Ciphertext-only attack).\"}, {\"key\": \"B\", \"text\": \"T\\u1ea5n c\\u00f4ng bi\\u1ebft tr\\u01b0\\u1edbc b\\u1ea3n r\\u00f5 (Known-plaintext attack).\"}, {\"key\": \"C\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ecdn tr\\u01b0\\u1edbc b\\u1ea3n r\\u00f5 (Chosen-plaintext attack - CPA).\"}, {\"key\": \"D\", \"text\": \"T\\u1ea5n c\\u00f4ng ch\\u1ecdn tr\\u01b0\\u1edbc b\\u1ea3n m\\u1eadt (Chosen-ciphertext attack - CCA).\"}]"', 'C', 'Tài liệu mô tả Tấn công chọn trước bản rõ (Chosen-plaintext attack - CPA) là: ''Kẻ tấn công có quyền truy cập không hạn chế vào thành phần mã hóa... Kẻ tấn công lựa chọn một số bản rõ (plaintext) theo ý muốn để mã hóa''.');
INSERT INTO public.questions VALUES (39, 4, 'Mật mã Vigenère sử dụng kỹ thuật gì để tăng cường độ an toàn so với mật mã Caesar?', '"[{\"key\": \"A\", \"text\": \"S\\u1eed d\\u1ee5ng nhi\\u1ec1u b\\u1ea3ng ch\\u1eef c\\u00e1i thay th\\u1ebf.\"}, {\"key\": \"B\", \"text\": \"Thay th\\u1ebf to\\u00e0n b\\u1ed9 kh\\u1ed1i k\\u00fd t\\u1ef1 c\\u00f9ng l\\u00fac.\"}, {\"key\": \"C\", \"text\": \"S\\u1eed d\\u1ee5ng kh\\u00f3a c\\u00f3 \\u0111\\u1ed9 d\\u00e0i b\\u1eb1ng b\\u1ea3n r\\u00f5.\"}, {\"key\": \"D\", \"text\": \"\\u00c1p d\\u1ee5ng ph\\u00e9p to\\u00e1n XOR.\"}]"', 'A', 'Tài liệu giải thích về mật mã Vigenère: ''Sử dụng kỹ thuật thay thế trên nhiều bảng chữ cái thay vì sử dụng đơn bảng chữ cái như từ điển mã''.');
INSERT INTO public.questions VALUES (40, 4, 'Trong mật mã khóa bất đối xứng, mỗi người dùng sở hữu bao nhiêu khóa?', '"[{\"key\": \"A\", \"text\": \"M\\u1ed9t kh\\u00f3a c\\u00f4ng khai.\"}, {\"key\": \"B\", \"text\": \"M\\u1ed9t kh\\u00f3a ri\\u00eang.\"}, {\"key\": \"C\", \"text\": \"M\\u1ed9t c\\u1eb7p kh\\u00f3a (kh\\u00f3a c\\u00f4ng khai v\\u00e0 kh\\u00f3a ri\\u00eang).\"}, {\"key\": \"D\", \"text\": \"Hai kh\\u00f3a c\\u00f4ng khai v\\u00e0 hai kh\\u00f3a ri\\u00eang.\"}]"', 'C', 'Tài liệu mô tả mật mã khóa bất đối xứng: ''Sử dụng một cặp khóa: Khóa công khai kU... Khóa riêng kR...''');


